const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageNumber, Header, Footer, TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

const BRAND_NAVY = "1B2A4A";
const BRAND_GOLD = "C9A84C";
const BRAND_LIGHT = "F5F0EA";
const BRAND_MID = "E8DDD0";
const WHITE = "FFFFFF";
const DARK_TEXT = "1A1A1A";
const SOFT_GRAY = "6B6B6B";

const border = { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD" };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 400, after: 200 },
    children: [new TextRun({ text, bold: true, size: 34, color: WHITE, font: "Arial" })],
    shading: { fill: BRAND_NAVY, type: ShadingType.CLEAR },
    indent: { left: 200, right: 200 },
  });
}

function h2(text) {
  return new Paragraph({
    spacing: { before: 360, after: 160 },
    children: [new TextRun({ text, bold: true, size: 26, color: BRAND_NAVY, font: "Arial" })],
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: BRAND_GOLD } },
  });
}

function h3(text) {
  return new Paragraph({
    spacing: { before: 240, after: 100 },
    children: [new TextRun({ text, bold: true, size: 22, color: BRAND_NAVY, font: "Arial" })],
  });
}

function body(text, options = {}) {
  return new Paragraph({
    spacing: { before: 80, after: 80 },
    children: [new TextRun({ text, size: 22, color: DARK_TEXT, font: "Arial", ...options })],
  });
}

function bullet(text, bold = false) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { before: 60, after: 60 },
    children: [new TextRun({ text, size: 22, color: DARK_TEXT, font: "Arial", bold })],
  });
}

function numbered(text) {
  return new Paragraph({
    numbering: { reference: "numbers", level: 0 },
    spacing: { before: 80, after: 80 },
    children: [new TextRun({ text, size: 22, color: DARK_TEXT, font: "Arial" })],
  });
}

function subBullet(text) {
  return new Paragraph({
    numbering: { reference: "subbullets", level: 0 },
    spacing: { before: 50, after: 50 },
    children: [new TextRun({ text, size: 20, color: SOFT_GRAY, font: "Arial" })],
  });
}

function note(text) {
  return new Paragraph({
    spacing: { before: 100, after: 100 },
    indent: { left: 400, right: 400 },
    shading: { fill: BRAND_LIGHT, type: ShadingType.CLEAR },
    children: [new TextRun({ text: `NOTE: ${text}`, size: 20, color: SOFT_GRAY, italics: true, font: "Arial" })],
  });
}

function highlight(text) {
  return new Paragraph({
    spacing: { before: 120, after: 120 },
    shading: { fill: BRAND_LIGHT, type: ShadingType.CLEAR },
    indent: { left: 200, right: 200 },
    children: [new TextRun({ text, size: 22, color: BRAND_NAVY, font: "Arial", bold: true })],
  });
}

function spacer() {
  return new Paragraph({ spacing: { before: 80, after: 80 }, children: [new TextRun("")] });
}

function divider() {
  return new Paragraph({
    spacing: { before: 100, after: 100 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 2, color: BRAND_MID } },
    children: [new TextRun("")],
  });
}

function sectionTag(text) {
  return new Paragraph({
    spacing: { before: 200, after: 80 },
    shading: { fill: BRAND_GOLD, type: ShadingType.CLEAR },
    indent: { left: 100 },
    children: [new TextRun({ text: `  ${text}  `, size: 18, bold: true, color: WHITE, font: "Arial" })],
  });
}

function inlineField(label, value) {
  return new Paragraph({
    spacing: { before: 80, after: 80 },
    children: [
      new TextRun({ text: `${label}: `, size: 22, bold: true, color: BRAND_NAVY, font: "Arial" }),
      new TextRun({ text: value, size: 22, color: DARK_TEXT, font: "Arial" }),
    ],
  });
}

const doc = new Document({
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } } }]
      },
      {
        reference: "subbullets",
        levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u25E6", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 1080, hanging: 360 } } } }]
      },
      {
        reference: "numbers",
        levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } } }]
      },
    ]
  },
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 34, bold: true, font: "Arial", color: WHITE },
        paragraph: { spacing: { before: 400, after: 200 }, outlineLevel: 0 } },
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    headers: {
      default: new Header({
        children: [
          new Paragraph({
            shading: { fill: BRAND_NAVY, type: ShadingType.CLEAR },
            spacing: { before: 0, after: 0 },
            children: [
              new TextRun({ text: "The Luxora Collective  |  Facebook Group Setup Guide  |  CONFIDENTIAL", size: 18, color: "AAAAAA", font: "Arial" })
            ]
          })
        ]
      })
    },
    children: [

      // COVER
      new Paragraph({
        spacing: { before: 600, after: 80 },
        alignment: AlignmentType.CENTER,
        shading: { fill: BRAND_NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", size: 40, bold: true, color: BRAND_GOLD, font: "Arial" })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 0 },
        alignment: AlignmentType.CENTER,
        shading: { fill: BRAND_NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "Facebook Group Launch", size: 28, color: WHITE, font: "Arial" })]
      }),
      new Paragraph({
        spacing: { before: 0, after: 0 },
        alignment: AlignmentType.CENTER,
        shading: { fill: BRAND_NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "Step-by-Step Setup Guide for Aanchal", size: 22, color: BRAND_GOLD, font: "Arial", italics: true })]
      }),
      new Paragraph({
        spacing: { before: 40, after: 600 },
        alignment: AlignmentType.CENTER,
        shading: { fill: BRAND_NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "Prepared by The Luxora Collective  |  Bethany Anne, Co-Founder & CEO", size: 18, color: "AAAAAA", font: "Arial" })]
      }),
      spacer(),

      // OVERVIEW
      h2("Overview"),
      body("This document gives you everything you need to create, configure, and launch our Facebook Group from start to finish. Bethany will be added as Admin once the group is live. Your role is to create it, manage daily activity, approve members, and monitor conversations. Read this fully before you begin."),
      spacer(),

      // GROUP NAME OPTIONS
      h2("Recommended Group Names"),
      body("All five names below have been chosen for availability likelihood and brand alignment. Check each one inside Facebook before committing. Go with whichever is not taken, in the order listed."),
      spacer(),

      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [3500, 5860],
        rows: [
          new TableRow({
            children: [
              new TableCell({ borders, shading: { fill: BRAND_NAVY, type: ShadingType.CLEAR }, width: { size: 3500, type: WidthType.DXA }, margins: { top: 100, bottom: 100, left: 160, right: 160 },
                children: [new Paragraph({ children: [new TextRun({ text: "Group Name", bold: true, size: 20, color: WHITE, font: "Arial" })] })] }),
              new TableCell({ borders, shading: { fill: BRAND_NAVY, type: ShadingType.CLEAR }, width: { size: 5860, type: WidthType.DXA }, margins: { top: 100, bottom: 100, left: 160, right: 160 },
                children: [new Paragraph({ children: [new TextRun({ text: "Why It Works", bold: true, size: 20, color: WHITE, font: "Arial" })] })] }),
            ]
          }),
          ...[
            ["The MedSpa Growth Collective", "Mirrors our brand name. Signals a peer community built around growth. Clean and professional."],
            ["MedSpa Owners Inner Circle", "Creates an exclusivity frame immediately. Owners respond to this language."],
            ["The Aesthetic Business Society", "Elevated, movement-forward. Feels less like a generic group and more like a membership."],
            ["MedSpa CEO Table", "Aspirational positioning. Short, memorable, filters for serious operators."],
            ["The Luxe MedSpa Network", "Brand-adjacent. Feminine, elevated, attracts the clientele we serve."],
          ].map((row, i) => new TableRow({
            children: [
              new TableCell({ borders, shading: { fill: i % 2 === 0 ? BRAND_LIGHT : WHITE, type: ShadingType.CLEAR }, width: { size: 3500, type: WidthType.DXA }, margins: { top: 100, bottom: 100, left: 160, right: 160 },
                children: [new Paragraph({ children: [new TextRun({ text: row[0], size: 20, bold: true, color: BRAND_NAVY, font: "Arial" })] })] }),
              new TableCell({ borders, shading: { fill: i % 2 === 0 ? BRAND_LIGHT : WHITE, type: ShadingType.CLEAR }, width: { size: 5860, type: WidthType.DXA }, margins: { top: 100, bottom: 100, left: 160, right: 160 },
                children: [new Paragraph({ children: [new TextRun({ text: row[1], size: 20, color: DARK_TEXT, font: "Arial" })] })] }),
            ]
          }))
        ]
      }),
      spacer(),

      // STEP BY STEP
      h2("Step-by-Step Setup Instructions"),
      note("Complete all steps in order. Do not skip ahead. Screenshots are not included in this document but each field name matches exactly what you will see on screen."),
      spacer(),

      // STEP 1
      sectionTag("STEP 1"),
      h3("Create the Group"),
      numbered("Log into Facebook using the Luxora business account credentials (or your own account, as we will transfer admin after)."),
      numbered("On the left sidebar, click Groups, then click the green Create New Group button."),
      numbered("Enter the group name from the list above. Use the first available option."),
      numbered("Set Privacy to Private. This is required. Do not choose Public."),
      numbered("Under Visible, select Visible (anyone can find it, but must request to join). Do not select Hidden."),
      numbered("Click Create."),
      spacer(),
      note("Private + Visible is the correct combination. Public groups are not appropriate for a professional community. Hidden groups cannot grow organically."),
      spacer(),

      // STEP 2
      sectionTag("STEP 2"),
      h3("Configure Group Settings"),
      body("After the group is created, go to Manage Group in the left sidebar, then click Settings. Complete each field below."),
      spacer(),
      h3("Group Description"),
      body("Copy and paste this exactly into the Description field:"),
      spacer(),
      highlight("This group is for independent medspa owners and small-group practice operators who are serious about growth. Whether you are scaling revenue, building a team, improving client retention, launching memberships, or navigating the business side of aesthetics, this is your space to ask questions, get real answers, and connect with owners who get it."),
      spacer(),
      highlight("No spam. No sales pitches. No vendors promoting products without permission. This is a peer community, not an ad board."),
      spacer(),
      highlight("Share wins. Ask questions. Get feedback. Grow."),
      spacer(),
      body("Managed by The Luxora Collective, a medspa growth consultancy helping independent owners build more profitable, sustainable businesses. Learn more at theluxoracollective.co"),
      spacer(),
      h3("Location"),
      body("Leave blank or enter United States if prompted."),
      spacer(),
      h3("Tags"),
      body("Add the following tags if the field is available: medspa, aesthetics, business, entrepreneurship, medical spa, medspa owner, small business."),
      spacer(),
      h3("Post Approval"),
      body("Turn ON Approve All Posts. This means every post must be reviewed before it appears. Check this queue at least once per day."),
      spacer(),
      h3("Member Approval"),
      body("Turn ON Membership Request Review. All join requests must be manually approved."),
      spacer(),
      h3("Group Rules (Meta Compliance)"),
      body("Go to Manage Group, then Group Rules. Add the following rules one by one:"),
      spacer(),
      bullet("Be Respectful: Treat all members with professionalism. No personal attacks, name-calling, or hostile language.", true),
      subBullet("No harassment of any kind will be tolerated."),
      bullet("No Spam or Unsolicited Promotion: Do not post links, products, or services without admin approval.", true),
      subBullet("This includes tagging vendors, sharing affiliate links, or promoting your own services in posts."),
      bullet("Stay on Topic: Posts must be relevant to medspa operations, business growth, or the aesthetics industry.", true),
      subBullet("Off-topic posts will be removed."),
      bullet("No Misinformation: Do not share medical claims or clinical advice that is not supported by evidence.", true),
      subBullet("Always recommend members consult qualified professionals."),
      bullet("Confidentiality: What is shared here stays here. Respect the privacy of other members.", true),
      bullet("Admins Have Final Say: Admin decisions on posts, members, and content are final.", true),
      spacer(),

      // STEP 3
      sectionTag("STEP 3"),
      h3("Set Up Membership Questions"),
      body("Go to Manage Group, then Membership Questions. Click Add Question. Add all three questions below. These filter out spammers and non-qualifying members."),
      spacer(),
      body("Question 1 (Multiple Choice):", { bold: true }),
      highlight("What best describes your current role?"),
      bullet("I own a medspa or aesthetic practice"),
      bullet("I am a partner or co-owner"),
      bullet("I manage a medspa but do not own it"),
      bullet("I am a student, vendor, or industry professional"),
      spacer(),
      note("If someone selects the last option, evaluate them carefully. Most spammers and vendors will select this or skip the question."),
      spacer(),
      body("Question 2 (Text Response):", { bold: true }),
      highlight("What is the name of your medspa or practice, and approximately how long have you been in business?"),
      spacer(),
      note("This filters casual lurkers and bots. Anyone who can not answer this is not your target member."),
      spacer(),
      body("Question 3 (Text Response):", { bold: true }),
      highlight("What is one challenge you are currently facing in your medspa business that you are hoping this community can help with?"),
      spacer(),
      note("This question tells you exactly what they need and helps you serve them immediately if accepted. Save these responses. They are market research."),
      spacer(),
      body("Turn ON Require Answers. Members must complete all questions before their request is reviewed."),
      spacer(),

      // STEP 4
      sectionTag("STEP 4"),
      h3("Add Bethany as Admin"),
      numbered("From the left sidebar, click Members."),
      numbered("Find Bethany's Facebook profile. Search by name: Bethany Anne."),
      numbered("Click the three-dot menu next to her name."),
      numbered("Select Invite as Admin."),
      numbered("She will receive a notification and must accept the invite."),
      numbered("Once accepted, her role will show as Admin."),
      spacer(),
      note("Until Bethany accepts, she will not have admin access. Send her a direct message to let her know the invite is waiting."),
      spacer(),

      // STEP 5
      sectionTag("STEP 5"),
      h3("Your Ongoing Role as Group Monitor"),
      body("Once the group is live, your daily responsibilities are:"),
      spacer(),
      h3("Every Day"),
      bullet("Check and approve or decline all pending member requests"),
      bullet("Review all posts in the approval queue. Approve relevant posts, decline spam"),
      bullet("Respond to any comments or questions from members with a brief acknowledgment if needed"),
      bullet("Flag any problematic posts or members for Bethany before taking action"),
      spacer(),
      h3("Every Week"),
      bullet("Post one piece of content to keep the group active (question prompt, industry stat, quick tip)"),
      bullet("Check for any rule violations and remove offending posts"),
      bullet("Send Bethany a brief weekly summary: new member count, top post of the week, any issues"),
      spacer(),
      h3("Member Approval Criteria"),
      body("Approve if:"),
      bullet("They answered all three questions"),
      bullet("They identify as an owner, partner, or operator"),
      bullet("Their profile looks real (has a photo, posts, connections)"),
      spacer(),
      body("Decline if:"),
      bullet("They skipped the questions"),
      bullet("They identify as a vendor, student, or unrelated professional"),
      bullet("Their profile looks fake or brand new with no activity"),
      spacer(),

      // STEP 6
      sectionTag("STEP 6"),
      h3("Meta Compliance Requirements"),
      body("Meta requires all groups to follow their Community Standards and Group Rules policies. Here is what you need to stay compliant:"),
      spacer(),
      bullet("Published group rules must be added and visible to members. Complete Step 2 above."),
      bullet("Do not allow posts that contain misleading health claims, fake medical advice, or before/after photos that violate health advertising policies."),
      bullet("Do not allow any post that promotes illegal services or violates HIPAA by sharing identifiable patient information."),
      bullet("Do not allow spam, coordinated inauthentic behavior, or posts that link to low-quality external sites."),
      bullet("Regularly remove inactive or fake accounts. You can do this by going to Members and filtering by Last Active."),
      bullet("If Meta flags a post for review, take action within 24 hours. Delaying can result in admin restrictions."),
      spacer(),
      note("Meta can restrict group creation or activity if your group generates repeated violations. Consistent moderation protects the group and your accounts."),
      spacer(),

      // PINNED POST
      sectionTag("STEP 7"),
      h3("First Pinned Post"),
      body("After the group is created and Bethany is admin, post this as the first piece of content and pin it to the top of the group. Post it from the Luxora account or from your own, then pin it."),
      spacer(),
      highlight("Welcome to [Group Name]. We built this community for one reason: medspa owners deserve a space where they can ask the hard questions and get real answers from people who actually understand this business."),
      spacer(),
      highlight("No fluff. No gatekeeping. No sales pitches."),
      spacer(),
      highlight("This is a peer community for owners, operators, and practice leaders in the aesthetics space. Drop in with your questions, share what is working, and connect with people who are building what you are building."),
      spacer(),
      highlight("To get us started: tell us your name, your medspa, and the one thing you wish someone had told you when you were starting out."),
      spacer(),
      highlight("Welcome in. We are glad you are here."),
      spacer(),
      body("After posting, click the three dots on the post and select Pin Post."),
      spacer(),

      // SUMMARY
      divider(),
      h2("Quick Reference Checklist"),
      body("Use this to confirm everything is complete before notifying Bethany:"),
      spacer(),
      bullet("Group created with correct name"),
      bullet("Privacy set to Private, Visibility set to Visible"),
      bullet("Description added"),
      bullet("Post approval turned on"),
      bullet("Member approval turned on"),
      bullet("All six group rules added"),
      bullet("All three membership questions added and set to Required"),
      bullet("Bethany invited as Admin"),
      bullet("Pinned welcome post published"),
      bullet("Bethany notified that group is live and invite is pending"),
      spacer(),
      note("Once Bethany accepts the admin invite, your role shifts to Monitor. She will take over any strategic decisions about the group direction. You handle daily operations."),
      spacer(),
      divider(),
      new Paragraph({
        spacing: { before: 200, after: 80 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "The Luxora Collective  |  theluxoracollective.co", size: 18, color: SOFT_GRAY, font: "Arial" })]
      }),
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/mnt/user-data/outputs/Luxora_Facebook_Group_Setup_Guide.docx", buffer);
  console.log("Done");
});

