      numbered("On the left sidebar, click Groups, then click the green Create New Group button."),
      numbered("Enter the group name from the list above. Use the first available option."),
      numbered("Set Privacy to Private. This is required. Do not choose Public."),
      numbered("Under Visible, select Visible (anyone can find it, but must request to join). Do not select Hidden."),
      numbered("Click Create."),
      spacer(),
      note("Private + Visible is the correct combination. Public groups are not appropriate for a professional community. Hidden groups cannot grow organically."),
      spacer(),

      // STEP 2
      sectionTag("STEP 2"),
      h3("Configure Group Settings"),
      body("After the group is created, go to Manage Group in the left sidebar, then click Settings. Complete each field below."),
      spacer(),
      h3("Group Description"),
      body("Copy and paste this exactly into the Description field:"),
      spacer(),
      highlight("This group is for independent medspa owners and small-group practice operators who are serious about growth. Whether you are scaling revenue, building a team, improving client retention, launching memberships, or navigating the business side of aesthetics, this is your space to ask questions, get real answers, and connect with owners who get it."),
      spacer(),
      highlight("No spam. No sales pitches. No vendors promoting products without permission. This is a peer community, not an ad board."),
      spacer(),
      highlight("Share wins. Ask questions. Get feedback. Grow."),
      spacer(),
      body("Managed by The Luxora Collective, a medspa growth consultancy helping independent owners build more profitable, sustainable businesses. Learn more at theluxoracollective.co"),
      spacer(),
      h3("Location"),
      body("Leave blank or enter United States if prompted."),
      spacer(),
      h3("Tags"),
      body("Add the following tags if the field is available: medspa, aesthetics, business, entrepreneurship, medical spa, medspa owner, small business."),
      spacer(),
      h3("Post Approval"),
      body("Turn ON Approve All Posts. This means every post must be reviewed before it appears. Check this queue at least once per day."),
      spacer(),
      h3("Member Approval"),
      body("Turn ON Membership Request Review. All join requests must be manually approved."),
      spacer(),
      h3("Group Rules (Meta Compliance)"),
      body("Go to Manage Group, then Group Rules. Add the following rules one by one:"),
      spacer(),
      bullet("Be Respectful: Treat all members with professionalism. No personal attacks, name-calling, or hostile language.", true),
      subBullet("No harassment of any kind will be tolerated."),
      bullet("No Spam or Unsolicited Promotion: Do not post links, products, or services without admin approval.", true),
      subBullet("This includes tagging vendors, sharing affiliate links, or promoting your own services in posts."),
      bullet("Stay on Topic: Posts must be relevant to medspa operations, business growth, or the aesthetics industry.", true),
      subBullet("Off-topic posts will be removed."),
      bullet("No Misinformation: Do not share medical claims or clinical advice that is not supported by evidence.", true),
      subBullet("Always recommend members consult qualified professionals."),
      bullet("Confidentiality: What is shared here stays here. Respect the privacy of other members.", true),
      bullet("Admins Have Final Say: Admin decisions on posts, members, and content are final.", true),
      spacer(),

      // STEP 3
