const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, Header
} = require('docx');
const fs = require('fs');

const NAVY = "1B2A4A";
const GOLD = "C9A84C";
const LIGHT = "F5F0EA";
const MID = "E8DDD0";
const WHITE = "FFFFFF";
const DARK = "1A1A1A";
const GRAY = "6B6B6B";
const GREEN = "2D6A4F";
const GREEN_LIGHT = "D8F0E5";

const b = { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD" };
const borders = { top: b, bottom: b, left: b, right: b };
const noB = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noB, bottom: noB, left: noB, right: noB };

const sp = (before = 80, after = 80) => ({ spacing: { before, after } });

function spacer() { return new Paragraph({ ...sp(60,60), children: [new TextRun("")] }); }
function divider() {
  return new Paragraph({ ...sp(120,120), border: { bottom: { style: BorderStyle.SINGLE, size: 2, color: MID } }, children: [new TextRun("")] });
}

function heading(text) {
  return new Paragraph({
    ...sp(360, 160),
    children: [new TextRun({ text, bold: true, size: 26, color: NAVY, font: "Arial" })],
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD } },
  });
}

function subheading(text) {
  return new Paragraph({
    ...sp(200, 80),
    children: [new TextRun({ text, bold: true, size: 22, color: NAVY, font: "Arial" })],
  });
}

function body(text, options = {}) {
  return new Paragraph({
    ...sp(70, 70),
    children: [new TextRun({ text, size: 21, color: DARK, font: "Arial", ...options })],
  });
}

function note(text) {
  return new Paragraph({
    ...sp(100, 100),
    indent: { left: 200, right: 200 },
    shading: { fill: LIGHT, type: ShadingType.CLEAR },
    children: [new TextRun({ text: `Tip: ${text}`, size: 19, color: GRAY, italics: true, font: "Arial" })],
  });
}

function checkRow(task, detail, freq) {
  const freqColor = freq === "Daily" ? "1B5E20" : freq === "Weekly" ? "1A237E" : "4A235A";
  const freqBg = freq === "Daily" ? "E8F5E9" : freq === "Weekly" ? "E8EAF6" : "F3E5F5";
  return new TableRow({
    children: [
      // Checkbox
      new TableCell({
        borders, width: { size: 500, type: WidthType.DXA },
        shading: { fill: WHITE, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 160, right: 80 },
        verticalAlign: "center",
        children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "\u2610", size: 24, font: "Arial", color: NAVY })] })]
      }),
      // Task + detail
      new TableCell({
        borders, width: { size: 6560, type: WidthType.DXA },
        shading: { fill: WHITE, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 160, right: 160 },
        children: [
          new Paragraph({ children: [new TextRun({ text: task, bold: true, size: 21, color: DARK, font: "Arial" })] }),
          new Paragraph({ ...sp(40,40), children: [new TextRun({ text: detail, size: 19, color: GRAY, font: "Arial" })] }),
        ]
      }),
      // Frequency badge
      new TableCell({
        borders, width: { size: 1300, type: WidthType.DXA },
        shading: { fill: freqBg, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 120, right: 120 },
        verticalAlign: "center",
        children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: freq, bold: true, size: 18, color: freqColor, font: "Arial" })] })]
      }),
    ]
  });
}

function tableHeader() {
  return new TableRow({
    children: [
      new TableCell({ borders, width: { size: 500, type: WidthType.DXA }, shading: { fill: NAVY, type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 160, right: 80 },
        children: [new Paragraph({ children: [new TextRun({ text: "", size: 20, font: "Arial" })] })] }),
      new TableCell({ borders, width: { size: 6560, type: WidthType.DXA }, shading: { fill: NAVY, type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 160, right: 160 },
        children: [new Paragraph({ children: [new TextRun({ text: "Task", bold: true, size: 20, color: WHITE, font: "Arial" })] })] }),
      new TableCell({ borders, width: { size: 1300, type: WidthType.DXA }, shading: { fill: NAVY, type: ShadingType.CLEAR }, margins: { top: 100, bottom: 100, left: 120, right: 120 },
        children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Frequency", bold: true, size: 20, color: WHITE, font: "Arial" })] })] }),
    ]
  });
}

function sectionLabel(text, color = NAVY) {
  return new Paragraph({
    ...sp(240, 80),
    shading: { fill: color, type: ShadingType.CLEAR },
    indent: { left: 100 },
    children: [new TextRun({ text: `  ${text}  `, size: 18, bold: true, color: WHITE, font: "Arial" })],
  });
}

const doc = new Document({
  numbering: {
    config: [
      { reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
      { reference: "numbers", levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
    ]
  },
  styles: {
    default: { document: { run: { font: "Arial", size: 21 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 28, bold: true, font: "Arial", color: WHITE },
        paragraph: { spacing: { before: 300, after: 160 }, outlineLevel: 0 } },
    ]
  },
  sections: [{
    properties: {
      page: { size: { width: 12240, height: 15840 }, margin: { top: 1260, right: 1260, bottom: 1260, left: 1260 } }
    },
    headers: {
      default: new Header({
        children: [new Paragraph({
          shading: { fill: NAVY, type: ShadingType.CLEAR }, ...sp(0,0),
          children: [new TextRun({ text: "The Luxora Collective  |  Facebook Group Growth  |  Aanchal Task List", size: 17, color: "AAAAAA", font: "Arial" })]
        })]
      })
    },
    children: [

      // COVER BLOCK
      new Paragraph({
        ...sp(400, 0), alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", size: 36, bold: true, color: GOLD, font: "Arial" })]
      }),
      new Paragraph({
        ...sp(0, 0), alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "Facebook Group Growth", size: 26, color: WHITE, font: "Arial" })]
      }),
      new Paragraph({
        ...sp(0, 0), alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "Aanchal's Task List", size: 22, color: GOLD, italics: true, font: "Arial" })]
      }),
      new Paragraph({
        ...sp(0, 400), alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "Prepared by Bethany Anne, Co-Founder & CEO  |  theluxoracollective.co", size: 17, color: "AAAAAA", font: "Arial" })]
      }),
      spacer(),

      // INTRO
      body("This is your complete task list for growing the Facebook Group. Every task below can be done without Bethany. Work through the Daily tasks first each morning, then move into Weekly and Ongoing as time allows. Flag anything unusual for Bethany before taking action."),
      spacer(),

      // LEGEND
      new Table({
        width: { size: 8360, type: WidthType.DXA },
        columnWidths: [1200, 1200, 1200, 4760],
        rows: [
          new TableRow({ children: [
            new TableCell({ borders: noBorders, width: { size: 1200, type: WidthType.DXA }, shading: { fill: "E8F5E9", type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 80 },
              children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Daily", bold: true, size: 19, color: "1B5E20", font: "Arial" })] })] }),
            new TableCell({ borders: noBorders, width: { size: 1200, type: WidthType.DXA }, shading: { fill: "E8EAF6", type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 80, right: 80 },
              children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Weekly", bold: true, size: 19, color: "1A237E", font: "Arial" })] })] }),
            new TableCell({ borders: noBorders, width: { size: 1200, type: WidthType.DXA }, shading: { fill: "F3E5F5", type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 80, right: 120 },
              children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Ongoing", bold: true, size: 19, color: "4A235A", font: "Arial" })] })] }),
            new TableCell({ borders: noBorders, width: { size: 4760, type: WidthType.DXA }, shading: { fill: WHITE, type: ShadingType.CLEAR }, margins: { top: 80, bottom: 80, left: 120, right: 0 },
              children: [new Paragraph({ children: [new TextRun({ text: "Frequency key for each task row", size: 19, color: GRAY, italics: true, font: "Arial" })] })] }),
          ]})
        ]
      }),
      spacer(),

      // SECTION 1: DAILY
      sectionLabel("SECTION 1: DAILY GROUP MANAGEMENT", NAVY),
      spacer(),
      new Table({
        width: { size: 8360, type: WidthType.DXA },
        columnWidths: [500, 6560, 1300],
        rows: [
          tableHeader(),
          checkRow("Approve or decline member requests", "Review answers to all 3 membership questions. Approve owners and operators. Decline vendors, blank profiles, or anyone who skipped the questions.", "Daily"),
          checkRow("Review and approve post queue", "Check all pending posts. Approve relevant ones. Decline spam, off-topic posts, or anything promoting a product or service without permission.", "Daily"),
