const {
  Document, Packer, Paragraph, TextRun, BorderStyle, WidthType, ShadingType,
  LevelFormat, AlignmentType, Header
} = require('docx');
const fs = require('fs');

const NAVY = "1B2A4A";
const GOLD = "C9A84C";
const LIGHT = "F5F0EA";
const MID = "E8DDD0";
const WHITE = "FFFFFF";
const DARK = "1A1A1A";
const GRAY = "6B6B6B";

function spacer() {
  return new Paragraph({ spacing: { before: 60, after: 60 }, children: [new TextRun("")] });
}
function divider() {
  return new Paragraph({
    spacing: { before: 160, after: 160 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 2, color: MID } },
    children: [new TextRun("")]
  });
}
function weekLabel(week, category) {
  return new Paragraph({
    spacing: { before: 300, after: 100 },
    children: [
      new TextRun({ text: `WEEK ${week}  `, bold: true, size: 19, color: GOLD, font: "Arial" }),
      new TextRun({ text: `${category}`, size: 19, color: GRAY, font: "Arial" }),
    ]
  });
}
function postLine(text, opts = {}) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    children: [new TextRun({ text, size: 22, color: DARK, font: "Arial", ...opts })]
  });
}
function gap() {
  return new Paragraph({ spacing: { before: 100, after: 100 }, children: [new TextRun("")] });
}
function hashtags(text) {
  return new Paragraph({
    spacing: { before: 120, after: 60 },
    children: [new TextRun({ text, size: 18, color: GRAY, italics: true, font: "Arial" })]
  });
}

const posts = [
  {
    week: 1, category: "REVENUE",
    lines: [
      "Be honest with yourself for a second.",
      "",
      "Is your schedule full but your bank account still making you nervous?",
      "",
      "That gap has a name. Most of us just haven't looked at it yet.",
      "",
      "What do you think yours is?",
    ],
    tags: "#MedSpaOwner #RevenueStrategy #LuxoraCollective"
  },
  {
    week: 2, category: "PEER LEARNING",
    lines: [
      "Something is working in your practice right now.",
      "",
      "Maybe it's small. Maybe nobody else knows about it yet.",
      "",
      "Drop it below. One thing. Real answer only.",
    ],
    tags: "#MedSpaOwner #PeerLearning #LuxoraCollective"
  },
  {
    week: 3, category: "MINDSET",
    lines: [
      "You built this so you could have a life.",
      "",
      "Does it feel that way right now?",
      "",
      "No judgment. Just curious where everyone is sitting with that.",
    ],
    tags: "#MedSpaOwner #MedSpaLife #LuxoraCollective"
  },
  {
    week: 4, category: "POLL",
    lines: [
      "Where are you actually stuck right now?",
      "",
      "A) Money isn't where it should be",
      "B) I can't get out of my own way",
      "C) My team isn't it yet",
      "D) I don't even know, it just feels off",
      "",
      "Drop your letter. No performing.",
    ],
    tags: "#MedSpaOwner #HonestConversations #LuxoraCollective"
  },
  {
    week: 5, category: "PEER LEARNING",
    lines: [
      "What's the thing someone told you early on that you smiled and nodded at.",
      "",
      "And then had to learn the hard way anyway.",
      "",
      "Mine was about pricing. What was yours?",
    ],
    tags: "#MedSpaOwner #LearnFromEachOther #LuxoraCollective"
  },
  {
    week: 6, category: "OPERATIONS",
    lines: [
      "Was there a moment it stopped feeling like survival?",
      "",
      "Where you looked up and thought, okay. I think I've got this.",
      "",
      "What changed? And if you're not there yet, what does it feel like is in the way?",
    ],
    tags: "#MedSpaOwner #MedSpaGrowth #LuxoraCollective"
  },
  {
    week: 7, category: "REVENUE",
    lines: [
      "The new client excitement is real.",
      "",
      "But when's the last time you looked at what your existing clients are actually worth to you over a year?",
      "",
      "That number changes everything. Have you run it?",
    ],
    tags: "#MedSpaOwner #ClientRetention #LuxoraCollective"
  },
  {
    week: 8, category: "PEER LEARNING",
    lines: [
      "Tell me about a decision you were sure about.",
      "",
      "That didn't go the way you planned.",
      "",
      "What did it teach you that you couldn't have learned any other way?",
    ],
    tags: "#MedSpaOwner #RealTalk #LuxoraCollective"
  },
  {
    week: 9, category: "POLL",
    lines: [
      "When you're genuinely stuck, where does your clarity actually come from?",
      "",
      "A) Other owners who get it",
      "B) My numbers",
      "C) Someone outside who can see it clearly",
      "D) My gut, full stop",
      "",
      "Drop your letter. Curious if this changes the longer you're in it.",
    ],
    tags: "#MedSpaOwner #MedSpaLeadership #LuxoraCollective"
  },
  {
    week: 10, category: "MARKETING",
    lines: [
      "Think about your most loyal client.",
      "",
      "The one who sends everyone they know without being asked.",
      "",
      "What did you actually do to earn that? Because I don't think it was the treatment.",
    ],
    tags: "#MedSpaOwner #ClientExperience #LuxoraCollective"
  },
  {
    week: 11, category: "PEER LEARNING",
    lines: [
      "What's the one thing in your practice that if it broke tomorrow you'd actually panic?",
      "",
      "Name it. One line on why.",
      "",
      "This thread is going to be the most useful thing posted in here all month.",
    ],
    tags: "#MedSpaOwner #MedSpaOperations #LuxoraCollective"
  },
  {
    week: 12, category: "MINDSET",
    lines: [
      "What would your practice look like if it was actually running the way you imagined when you started?",
      "",
      "Not revenue. Just how it would feel.",
      "",
      "How far is that from where you are right now?",
    ],
    tags: "#MedSpaOwner #GrowthMindset #LuxoraCollective"
  },
  {
    week: 13, category: "PEER LEARNING",
    lines: [
      "What hire changed everything for you?",
      "",
      "And how long did you wait before you finally made it?",
      "",
      "If you're sitting on one right now, tell us what's actually stopping you.",
    ],
    tags: "#MedSpaOwner #MedSpaTeam #LuxoraCollective"
  },
  {
    week: 14, category: "OPERATIONS",
    lines: [
      "What did you have to let go of to grow?",
      "",
      "And be honest, how long did you hold on after you already knew you needed to let it go?",
    ],
    tags: "#MedSpaOwner #Delegation #LuxoraCollective"
  },
  {
    week: 15, category: "REVENUE",
    lines: [
      "There's a revenue conversation most of us keep putting off.",
      "",
      "Not with clients. With ourselves.",
      "",
      "Pricing that hasn't moved in two years. A service that looks profitable but isn't. Something we already know but haven't looked at yet.",
      "",
      "What's yours?",
    ],
    tags: "#MedSpaOwner #RevenueClarity #LuxoraCollective"
  },
  {
    week: 16, category: "MINDSET",
    lines: [
      "Last post of this rotation. Skipping the practice question.",
      "",
      "What did this quarter teach you about yourself?",
      "",
      "Not your business. You.",
    ],
    tags: "#MedSpaOwner #GrowthMindset #LuxoraCollective"
  },
];

const doc = new Document({
  numbering: { config: [] },
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 28, bold: true, font: "Arial", color: NAVY },
        paragraph: { spacing: { before: 300, after: 160 }, outlineLevel: 0 } },
    ]
  },
  sections: [{
    properties: {
      page: { size: { width: 12240, height: 15840 }, margin: { top: 1260, right: 1440, bottom: 1260, left: 1440 } }
    },
    headers: {
      default: new Header({
        children: [new Paragraph({
          shading: { fill: NAVY, type: ShadingType.CLEAR }, spacing: { before: 0, after: 0 },
          children: [new TextRun({ text: "The Luxora Collective  |  16-Week Group Posts  |  Short. Real. Theirs to answer.", size: 17, color: "AAAAAA", font: "Arial" })]
        })]
      })
    },
    children: [
      // COVER
      new Paragraph({ spacing: { before: 400, after: 0 }, alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", size: 38, bold: true, color: GOLD, font: "Arial" })] }),
      new Paragraph({ spacing: { before: 0, after: 0 }, alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "16 Weeks of Group Posts", size: 26, color: WHITE, font: "Arial" })] }),
      new Paragraph({ spacing: { before: 0, after: 400 }, alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "Short. Honest. Built to start real conversations.", size: 20, color: GOLD, italics: true, font: "Arial" })] }),
      spacer(),

      // NOTES
      new Paragraph({ spacing: { before: 160, after: 120 }, children: [new TextRun({ text: "A Note on Tone", bold: true, size: 24, color: NAVY, font: "Arial" })],
        border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD } } }),
      new Paragraph({ spacing: { before: 80, after: 80 }, children: [new TextRun({ text: "Every post in here is short on purpose. The goal isn't to educate. It's to open something up. Post it, walk away, and let the comments come. Resist the urge to add context or explain yourself. The shorter it is, the more they fill in the space with their own truth. That's where the conversation lives.", size: 21, color: DARK, font: "Arial" })] }),
      spacer(),
      new Paragraph({ spacing: { before: 80, after: 80 }, children: [new TextRun({ text: "One post per week. Same day every week. Reply to every comment in the first hour if you can. That first hour determines whether a post becomes a thread or disappears.", size: 21, color: DARK, font: "Arial" })] }),
      spacer(),
      divider(),

      // POSTS
      ...posts.flatMap((post, i) => [
        weekLabel(post.week, post.category),
        ...post.lines.map(line =>
          line === "" ? gap() : postLine(line)
        ),
        spacer(),
        hashtags(post.tags),
        i < posts.length - 1 ? divider() : spacer(),
      ]),

      spacer(),
      new Paragraph({ spacing: { before: 160, after: 80 }, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "The Luxora Collective  |  theluxoracollective.co", size: 17, color: GRAY, font: "Arial" })] }),
    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync("/mnt/user-data/outputs/Luxora_16Week_Posts_Final.docx", buf);
  console.log("Done");
});

