const {
  Document, Packer, Paragraph, TextRun, BorderStyle, ShadingType,
  AlignmentType, Header, WidthType
} = require('docx');
const fs = require('fs');

const NAVY = "1B2A4A";
const GOLD = "C9A84C";
const LIGHT = "F5F0EA";
const MID = "E8DDD0";
const WHITE = "FFFFFF";
const DARK = "1A1A1A";
const GRAY = "777777";

function spacer() {
  return new Paragraph({ spacing: { before: 80, after: 80 }, children: [new TextRun("")] });
}
function divider() {
  return new Paragraph({
    spacing: { before: 200, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 2, color: MID } },
    children: [new TextRun("")]
  });
}
function weekLabel(week, category) {
  return new Paragraph({
    spacing: { before: 360, after: 80 },
    children: [
      new TextRun({ text: `Week ${week}  `, bold: true, size: 20, color: GOLD, font: "Arial" }),
      new TextRun({ text: category, size: 20, color: GRAY, font: "Arial" }),
    ]
  });
}
function line(text, opts = {}) {
  return new Paragraph({
    spacing: { before: 80, after: 80 },
    children: [new TextRun({ text, size: 23, color: DARK, font: "Arial", ...opts })]
  });
}
function tags(text) {
  return new Paragraph({
    spacing: { before: 140, after: 60 },
    children: [new TextRun({ text, size: 18, color: GRAY, italics: true, font: "Arial" })]
  });
}

const posts = [
  {
    week: 1, category: "Revenue",
    content: `Okay real talk.

I work with medspas all over the country and I hear this one constantly: "I'm fully booked but I still feel broke."

And honestly? It's one of the most common things I see. Full schedule, exhausted team, and the bank account still gives you anxiety.

It's almost never about getting more clients. It's about where the money's going quiet.

Where do you feel like yours is slipping? I actually want to know because I probably see it in practices just like yours.`,
    hashtags: "#MedSpaOwner #RevenueStrategy #LuxoraCollective"
  },
  {
    week: 2, category: "Peer Learning",
    content: `I've been thinking about something and I want to hear your take.

What's one thing working really well in your practice right now that you don't talk about enough?

Not a humble brag. Like actually, what's quietly winning for you? Because I talk to owners every week and the good stuff rarely gets shared out loud. It stays in your head or in a Slack with your manager.

Drop it below. We all deserve to steal something good this week.`,
    hashtags: "#MedSpaOwner #PeerLearning #LuxoraCollective"
  },
  {
    week: 3, category: "Mindset",
    content: `Can I be honest about something I see a lot?

So many owners I work with built something genuinely incredible and then quietly became its most exhausted employee.

And we don't talk about it because we're supposed to love what we built. And we do. But love doesn't mean you can't also be completely depleted by it.

You're allowed to want it to run without you holding everything together. That's not laziness. That's the whole point.

Where are you at with that honestly?`,
    hashtags: "#MedSpaOwner #MedSpaLife #LuxoraCollective"
  },
  {
    week: 4, category: "Poll",
    content: `Okay I want a real answer on this one, not the polished version.

Right now, what's the thing that's actually in your way?

A) The money isn't where it should be and I don't totally know why
B) I can't get out of my own way and I know it
C) My team isn't right and it's costing me
D) Honestly I can't even name it, it just feels off

Drop your letter. No one's performing in here, that's the whole point of this group.`,
    hashtags: "#MedSpaOwner #HonestConversations #LuxoraCollective"
  },
  {
    week: 5, category: "Peer Learning",
    content: `I've been thinking about something and I want to hear your take on it.

What's the thing someone told you early on that you completely brushed off. And then had to learn the hard way anyway.

Mine that I hear from owners all the time is pricing. Someone tells them undercharging isn't being humble, it's a habit. They nod. Then spend two more years doing it.

We all have that thing. What was yours? Because someone newer in this group needs to read your answer.`,
    hashtags: "#MedSpaOwner #LearnFromEachOther #LuxoraCollective"
  },
  {
    week: 6, category: "Operations",
    content: `Okay real talk, was there a moment it stopped feeling like you were just surviving?

Like you looked up one day and thought, okay, I actually have a handle on this.

I talk to owners constantly who are waiting for that feeling and I'm always curious what actually got them there. A hire, a system, finally letting something go.

What was it for you? And if you're still in the thick of it, what does it feel like is in the way?`,
    hashtags: "#MedSpaOwner #MedSpaGrowth #LuxoraCollective"
  },
  {
    week: 7, category: "Revenue",
    content: `I've been thinking about something and I see this gap in almost every practice I work with.

We celebrate new clients. We talk about new clients. We run ads for new clients.

But when's the last time you actually looked at what your existing clients are worth to you over a full year?

That number will change how you think about everything. Retention, rebooking, your membership offer, all of it.

Have you run it? Because if not that's probably where I'd start.`,
    hashtags: "#MedSpaOwner #ClientRetention #LuxoraCollective"
  },
  {
    week: 8, category: "Peer Learning",
    content: `Okay real talk, the one nobody loves but everybody needs.

Tell me about a decision you were completely sure about. That did not go the way you planned.

What did it actually teach you?

I ask because I work with a lot of owners and the lessons that stick are never from the wins. They're from the hire you were so sure about, the service that flopped, the investment that hurt.

The real education is in this room. Let's actually use it.`,
    hashtags: "#MedSpaOwner #RealTalk #LuxoraCollective"
  },
  {
    week: 9, category: "Poll",
    content: `I've been thinking about this one a lot lately.

When you're genuinely stuck on something in your business, where does the useful clarity actually come from for you?

A) Other owners who actually get it, conversations like this one
B) My numbers, the data usually tells me what to do
C) Someone outside who can see what I'm too close to see
D) My gut, I've been doing this long enough to trust it

Drop your letter. I'm curious if this changes the longer you're in it because I think it does.`,
    hashtags: "#MedSpaOwner #MedSpaLeadership #LuxoraCollective"
  },
  {
    week: 10, category: "Marketing",
    content: `I've been thinking about something and I want to hear your take.

Think about your most loyal client. The one who sends you everyone they know without being asked and would never dream of going anywhere else.

What did your practice actually do to earn that relationship?

I ask because I work with a lot of medspas and it's almost never the treatment itself. It's something in the way they felt. And most owners can't fully name it when I ask.

Can you?`,
    hashtags: "#MedSpaOwner #ClientExperience #LuxoraCollective"
  },
  {
    week: 11, category: "Peer Learning",
    content: `Okay real talk, practical one this week.

What's the one tool or system in your practice that if it disappeared tomorrow you'd actually panic?

Not a concept. The actual thing, the software, the process, the person, whatever it is.

Drop the name and one line on why. I talk to owners all the time who are still running things in a way that's costing them and they don't even know what they're missing. This thread is going to help somebody.`,
    hashtags: "#MedSpaOwner #MedSpaOperations #LuxoraCollective"
  },
  {
    week: 12, category: "Mindset",
    content: `I've been thinking about this one and I keep coming back to it.

If your practice was actually running the way you pictured it when you started, what would feel different?

Not the revenue number. Just the feeling of it. Your Monday morning. Whether you feel like you're building something or just keeping up.

I ask because I see the gap between where owners are and where they imagined being, and it's usually not that far. But something's in the way.

What is it for you right now?`,
    hashtags: "#MedSpaOwner #GrowthMindset #LuxoraCollective"
  },
  {
    week: 13, category: "Peer Learning",
    content: `Okay real talk on hiring because I see this constantly.

We know what the right hire would change. We can feel the gap every single week. And then we talk ourselves out of it for months.

What's the hire that changed everything for you? And how long did you wait before you made it?

And if you're sitting on one right now, tell us what's actually stopping you. Not the polished version. The real one. Because somebody in here has been in that exact spot.`,
    hashtags: "#MedSpaOwner #MedSpaTeam #LuxoraCollective"
  },
  {
    week: 14, category: "Operations",
    content: `I've been thinking about something and I want to be honest about what I see.

The owners I work with who grow the fastest all have one thing in common. At some point they let go of something they were really good at holding.

A task they knew needed to be delegated but couldn't release. A standard they carried personally because no one else would do it the same way. A way of running things that worked when it was just them.

What did you have to let go of to grow? And how long did you hold on after you already knew?`,
    hashtags: "#MedSpaOwner #Delegation #LuxoraCollective"
  },
  {
    week: 15, category: "Revenue",
    content: `Okay real talk about the conversation most of us keep putting off.

Not with clients. With ourselves.

I see it all the time working with medspas. Pricing that hasn't moved in two years. A service that keeps the schedule full but isn't actually profitable when you do the real math. Retention numbers nobody's looked at lately.

We already know it's there. We just haven't sat down with it yet.

What's the revenue conversation you've been avoiding? You can say it here. This group gets it.`,
    hashtags: "#MedSpaOwner #RevenueClarity #LuxoraCollective"
  },
  {
    week: 16, category: "Mindset",
    content: `Last post of this rotation and I'm skipping the business question.

What did this quarter actually teach you about yourself?

Not your practice. Not your team. Not your numbers.

You.

Because I've worked with enough owners to know that the business stuff is usually a reflection of something personal we're working through. And the ones who grow the fastest are the ones willing to look at both.

I'll go first in the comments. Drop yours.`,
    hashtags: "#MedSpaOwner #GrowthMindset #LuxoraCollective"
  },
];

const doc = new Document({
  numbering: { config: [] },
  styles: {
    default: { document: { run: { font: "Arial", size: 23 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 28, bold: true, font: "Arial", color: NAVY },
        paragraph: { spacing: { before: 300, after: 160 }, outlineLevel: 0 } },
    ]
  },
  sections: [{
    properties: {
      page: { size: { width: 12240, height: 15840 }, margin: { top: 1260, right: 1440, bottom: 1260, left: 1440 } }
    },
    headers: {
      default: new Header({
        children: [new Paragraph({
          shading: { fill: NAVY, type: ShadingType.CLEAR }, spacing: { before: 0, after: 0 },
          children: [new TextRun({ text: "The Luxora Collective  |  16-Week Group Posts  |  Bethany's Voice", size: 17, color: "AAAAAA", font: "Arial" })]
        })]
      })
    },
    children: [
      new Paragraph({ spacing: { before: 400, after: 0 }, alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", size: 38, bold: true, color: GOLD, font: "Arial" })] }),
      new Paragraph({ spacing: { before: 0, after: 0 }, alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "16-Week Facebook Group Posts", size: 26, color: WHITE, font: "Arial" })] }),
      new Paragraph({ spacing: { before: 0, after: 400 }, alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "Conversational. Real. Written in your voice.", size: 20, color: GOLD, italics: true, font: "Arial" })] }),
      spacer(),

      new Paragraph({ spacing: { before: 160, after: 120 },
        border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD } },
        children: [new TextRun({ text: "How These Work", bold: true, size: 24, color: NAVY, font: "Arial" })] }),
      new Paragraph({ spacing: { before: 80, after: 80 },
        children: [new TextRun({ text: "Every post rotates between two natural entry points: 'I've been thinking about something and I want to hear your take' or 'Okay real talk.' Both feel like you. Post once a week, same day, and reply to early comments personally. The conversation starts with you showing up like a human, not a brand.", size: 21, color: DARK, font: "Arial" })] }),
      spacer(),
      divider(),

      ...posts.flatMap((post, i) => {
        const contentLines = post.content.split('\n');
        return [
          weekLabel(post.week, post.category),
          ...contentLines.map(l => l.trim() === "" ? spacer() : line(l)),
          spacer(),
          tags(post.hashtags),
          i < posts.length - 1 ? divider() : spacer(),
        ];
      }),

      spacer(),
      new Paragraph({ spacing: { before: 160, after: 80 }, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "The Luxora Collective  |  theluxoracollective.co", size: 17, color: GRAY, font: "Arial" })] }),
    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync("/mnt/user-data/outputs/Luxora_16Week_Posts_YourVoice.docx", buf);
  console.log("Done");
});

