const {
  Document, Packer, Paragraph, TextRun, BorderStyle, ShadingType,
  AlignmentType, Header
} = require('docx');
const fs = require('fs');

const NAVY = "1B2A4A";
const GOLD = "C9A84C";
const MID = "E8DDD0";
const WHITE = "FFFFFF";
const DARK = "1A1A1A";
const GRAY = "777777";
const LIGHT = "F5F0EA";

function sp(before = 80, after = 80) { return { spacing: { before, after } }; }
function spacer() { return new Paragraph({ ...sp(80,80), children: [new TextRun("")] }); }
function divider() {
  return new Paragraph({
    ...sp(240, 240),
    border: { bottom: { style: BorderStyle.SINGLE, size: 2, color: MID } },
    children: [new TextRun("")]
  });
}
function dayLabel(day, type) {
  return new Paragraph({
    ...sp(360, 80),
    children: [
      new TextRun({ text: day, bold: true, size: 21, color: NAVY, font: "Arial" }),
      new TextRun({ text: `   ${type}`, size: 19, color: GRAY, font: "Arial", italics: true }),
    ]
  });
}
function postBody(text) {
  return text.split('\n').map(l =>
    l.trim() === ""
      ? new Paragraph({ ...sp(90,90), children: [new TextRun("")] })
      : new Paragraph({ ...sp(60,60), children: [new TextRun({ text: l, size: 23, color: DARK, font: "Arial", lineRule: "auto" })] })
  );
}
function hashLine(text) {
  return new Paragraph({
    ...sp(160, 60),
    children: [new TextRun({ text, size: 18, color: GRAY, italics: true, font: "Arial" })]
  });
}

const posts = [

  // WEEK 1
  {
    day: "Week 1, Monday", type: "Conversation Starter",
    text: `I've been working alongside medspa owners for decades and there's one question I never get tired of asking.

If you could go back and whisper one thing to yourself on the day you opened your doors, what would it be?

Not the business advice. The real stuff. The thing nobody tells you about what this life actually asks of you.

I'll read every single answer in this thread.`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaLife"
  },
  {
    day: "Week 1, Wednesday", type: "Hard Question",
    text: `Be honest with yourself for a second.

Is there a version of your practice you've been putting off building because some part of you isn't sure you're ready for it?

What does that version look like? And what's actually in the way?`,
    hashtags: "#MedSpaOwner #LuxoraCollective #GrowthMindset"
  },
  {
    day: "Week 1, Friday", type: "Share Your Win",
    text: `Something I've learned from working with practices of every size and stage.

The wins that matter most are almost never the ones that make the highlight reel.

What's something that happened in your practice recently that nobody clapped for but you felt in your bones?

Share it here. We'll clap.`,
    hashtags: "#MedSpaOwner #LuxoraCollective #RealTalk"
  },

  // WEEK 2
  {
    day: "Week 2, Monday", type: "Traction Moment",
    text: `After decades in this industry, the question I find myself asking owners more than any other is this one.

What was the specific moment you felt like you finally had traction?

Not just busy. Not just surviving. Actually moving.

Was it a hire? A system that finally held? A decision you made that scared you a little?

Tell me exactly what it was. The more specific the better.`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaGrowth"
  },
  {
    day: "Week 2, Wednesday", type: "Hard Question",
    text: `Who in your practice is doing a job that you know in your gut isn't the right fit anymore?

You don't have to name names. But sit with the question.

How long have you known? And what's it actually costing you to wait?`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaTeam"
  },
  {
    day: "Week 2, Friday", type: "Peer Learning",
    text: `I want to tap into something this group has that no course or consultant can replicate.

What's the one thing you know now about running a medspa that you wish had been in a manual somewhere?

The thing that took you too long to figure out. Drop it below. Write it like you're handing it to someone who's exactly where you were two years ago.`,
    hashtags: "#MedSpaOwner #LuxoraCollective #PeerLearning"
  },

  // WEEK 3
  {
    day: "Week 3, Monday", type: "Emotional Check-In",
    text: `Can I ask something that doesn't get asked enough in business spaces?

How are you actually doing?

Not your practice. Not your numbers. Not your team.

You. The person who built this thing and shows up for it every single day.

This is a safe place to answer honestly.`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaLife"
  },
  {
    day: "Week 3, Wednesday", type: "Hard Question",
    text: `What's the thing in your practice you keep saying you'll fix when things slow down?

Things aren't going to slow down.

What would it actually take to fix it now?`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaOperations"
  },
  {
    day: "Week 3, Friday", type: "The Hire That Changed Everything",
    text: `One of my favorite conversations to have with owners is about the hire that changed everything.

Not the first hire. The right one. The person who walked in and something shifted.

Who was it for you? What role were they in? And what did you finally get to stop carrying once they were there?`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaTeam"
  },

  // WEEK 4
  {
    day: "Week 4, Monday", type: "Advice to a New Owner",
    text: `If a brand new medspa owner sat down across from you today and said "just be straight with me, what do I need to know," what would you actually tell them?

Not the encouraging stuff. The real stuff.

The thing that took you longer than it should have to learn.`,
    hashtags: "#MedSpaOwner #LuxoraCollective #PeerLearning"
  },
  {
    day: "Week 4, Wednesday", type: "Hard Question",
    text: `Here's one I sit with a lot after years in this industry.

At what point does the thing you built for freedom start to feel like a different kind of trap?

And when you hit that wall, what did you do or what are you doing about it?`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaLife"
  },
  {
    day: "Week 4, Friday", type: "Close Out the Month",
    text: `Last post of the month and I want to end it with something simple.

What's one thing that happened in your practice this month that you're proud of?

Not what someone else would put on a highlight reel. What you know mattered.

End the month by saying it out loud. You earned that.`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaGrowth"
  },
];

const doc = new Document({
  numbering: { config: [] },
  styles: {
    default: { document: { run: { font: "Arial", size: 23 } } },
  },
  sections: [{
    properties: {
      page: { size: { width: 12240, height: 15840 }, margin: { top: 1260, right: 1440, bottom: 1260, left: 1440 } }
    },
    headers: {
      default: new Header({
        children: [new Paragraph({
          shading: { fill: NAVY, type: ShadingType.CLEAR }, spacing: { before: 0, after: 0 },
          children: [new TextRun({ text: "The Luxora Collective  |  Month 1 Group Posts  |  Conversation Starters", size: 17, color: "AAAAAA", font: "Arial" })]
        })]
      })
    },
    children: [

      // COVER
      new Paragraph({ ...sp(400, 0), alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", size: 38, bold: true, color: GOLD, font: "Arial" })] }),
      new Paragraph({ ...sp(0, 0), alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "Month 1 Facebook Group Posts", size: 26, color: WHITE, font: "Arial" })] }),
      new Paragraph({ ...sp(0, 400), alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "3 posts per week  |  Mon, Wed, Fri  |  Let them do the talking", size: 19, color: GOLD, italics: true, font: "Arial" })] }),
      spacer(),

      // POSTING NOTE
      new Paragraph({ ...sp(160, 100),
        border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD } },
        children: [new TextRun({ text: "Before You Post", bold: true, size: 24, color: NAVY, font: "Arial" })] }),
      new Paragraph({ ...sp(80, 80),
        children: [new TextRun({ text: "Every post here is a question, not a statement. The goal is to make the owners in this group feel like the experts in the room because they are. You're the one asking. They're the ones with the answers. Post it, show up in the comments, and let the conversation breathe.", size: 21, color: DARK, font: "Arial" })] }),
      spacer(),
      divider(),

      // POSTS
      ...posts.flatMap((post, i) => [
        dayLabel(post.day, post.type),
        ...postBody(post.text),
        spacer(),
        hashLine(post.hashtags),
        i < posts.length - 1 ? divider() : spacer(),
      ]),

      spacer(),
      new Paragraph({ ...sp(160, 80), alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "The Luxora Collective  |  theluxoracollective.co", size: 17, color: GRAY, font: "Arial" })] }),
    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync("/mnt/user-data/outputs/Luxora_Month1_GroupPosts.docx", buf);
  console.log("Done");
});

