const {
  Document, Packer, Paragraph, TextRun, BorderStyle, ShadingType,
  AlignmentType, Header
} = require('docx');
const fs = require('fs');

const NAVY = "1B2A4A";
const GOLD = "C9A84C";
const MID = "E8DDD0";
const WHITE = "FFFFFF";
const DARK = "1A1A1A";
const GRAY = "777777";

function sp(before = 80, after = 80) { return { spacing: { before, after } }; }
function spacer() { return new Paragraph({ ...sp(80,80), children: [new TextRun("")] }); }
function divider() {
  return new Paragraph({
    ...sp(240, 240),
    border: { bottom: { style: BorderStyle.SINGLE, size: 2, color: MID } },
    children: [new TextRun("")]
  });
}
function dayLabel(day, type) {
  return new Paragraph({
    ...sp(360, 80),
    children: [
      new TextRun({ text: day, bold: true, size: 21, color: NAVY, font: "Arial" }),
      new TextRun({ text: `   ${type}`, size: 19, color: GRAY, font: "Arial", italics: true }),
    ]
  });
}
function postBody(text) {
  return text.split('\n').map(l =>
    l.trim() === ""
      ? new Paragraph({ ...sp(90,90), children: [new TextRun("")] })
      : new Paragraph({ ...sp(60,60), children: [new TextRun({ text: l, size: 23, color: DARK, font: "Arial" })] })
  );
}
function hashLine(text) {
  return new Paragraph({
    ...sp(160, 60),
    children: [new TextRun({ text, size: 18, color: GRAY, italics: true, font: "Arial" })]
  });
}

const posts = [
  {
    day: "Week 1, Monday", type: "Open the Room",
    text: `Ok owners, it's time to help each other grow.

Let's get real for a second.

Where in your business are you quietly frustrated right now?

Not what looks good on the outside. Where you know something isn't clicking the way it should.

And more importantly… what have you already tried to fix it?`,
    hashtags: "#MedSpaOwner #LuxoraCollective #RealTalk"
  },
  {
    day: "Week 1, Wednesday", type: "Revenue",
    text: `Ok owners, let's talk truth, not highlight reels.

What is actually driving revenue in your business right now?

If you had to point to one or two things that are consistently bringing in real dollars, what are they?

And do you feel like you fully understand why they're working?`,
    hashtags: "#MedSpaOwner #LuxoraCollective #RevenueStrategy"
  },
  {
    day: "Week 1, Friday", type: "Reflection",
    text: `Ok owners, I want you to think back to when you first opened.

What did you believe would grow your business that ended up not working the way you thought?

Be honest. Ads, hiring, equipment, partnerships, anything.

What did it teach you?`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaGrowth"
  },
  {
    day: "Week 2, Monday", type: "Profit Leaks",
    text: `Ok owners, let's raise the level of this room.

Where do you feel like your business is leaking money right now?

Missed calls, no-shows, weak consults, low package conversion, clients not coming back…

Where do you know there's opportunity being left on the table?`,
    hashtags: "#MedSpaOwner #LuxoraCollective #RevenueStrategy"
  },
  {
    day: "Week 2, Wednesday", type: "Consistency",
    text: `Ok owners, real question.

Do you feel like your business is currently built for consistency or are you still riding waves?

Meaning… do you know where next month's revenue is coming from, or are you still having to figure it out every 30 days?

What does that feel like from the inside?`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaOperations"
  },
  {
    day: "Week 2, Friday", type: "Emotional Toll",
    text: `Ok owners, let's talk about something deeper.

What part of this business has taken the biggest emotional toll on you?

Team issues, cash flow pressure, marketing not working, feeling stuck…

This industry can look glamorous from the outside. But we all know that's not the full story.

You're safe to be honest here.`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaLife"
  },
  {
    day: "Week 3, Monday", type: "Wins",
    text: `Ok owners, flip side of that.

What's a moment recently where you thought, this is exactly why I built this?

A client result, a revenue milestone, a team win, a personal freedom moment…

Let's share some wins too. Drop it below.`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaWins"
  },
  {
    day: "Week 3, Wednesday", type: "Start From Scratch",
    text: `Ok owners, if you had to rebuild your business from scratch today…

What would you focus on in your first 90 days to get to profitability faster?

No fluff. What actually matters?

I want operator-level answers on this one.`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaGrowth"
  },
  {
    day: "Week 3, Friday", type: "Advice to Yourself",
    text: `Ok owners, this one's personal.

If you could go back and give yourself one piece of advice on the day you opened your doors, what would it be?

Not the business stuff. The real stuff. The thing nobody warned you about.

I'll read every single answer in this thread.`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaLife"
  },
  {
    day: "Week 4, Monday", type: "Biggest Constraint",
    text: `Ok owners, I want operator-level answers on this one.

Where is your biggest constraint right now?

Getting the right leads in the door
Turning consults into high-value clients
Getting your team to perform consistently
Keeping clients coming back

Drop your answer and tell us why. Because the answer changes everything about where to focus.`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaStrategy"
  },
  {
    day: "Week 4, Wednesday", type: "The Hire",
    text: `Ok owners, tell me about the hire that changed everything.

Not your first hire. The right one. The person who walked in and something in your business actually shifted.

What role were they in? What did you finally get to stop carrying once they were there?

And how long did you wait before you made that hire?`,
    hashtags: "#MedSpaOwner #LuxoraCollective #MedSpaTeam"
  },
  {
    day: "Week 4, Friday", type: "Busy vs. Growing",
    text: `Ok owners, last one for the month and it's the one I think about most.

What are you currently doing that feels busy… but deep down you know isn't actually growing your business?

We all have one.

What is it, and why are you still doing it?`,
    hashtags: "#MedSpaOwner #LuxoraCollective #RealTalk"
  },
];

const doc = new Document({
  numbering: { config: [] },
  styles: {
    default: { document: { run: { font: "Arial", size: 23 } } },
  },
  sections: [{
    properties: {
      page: { size: { width: 12240, height: 15840 }, margin: { top: 1260, right: 1440, bottom: 1260, left: 1440 } }
    },
    headers: {
      default: new Header({
        children: [new Paragraph({
          shading: { fill: NAVY, type: ShadingType.CLEAR }, spacing: { before: 0, after: 0 },
          children: [new TextRun({ text: "The Luxora Collective  |  Month 1 Group Posts  |  Bethany's Voice", size: 17, color: "AAAAAA", font: "Arial" })]
        })]
      })
    },
    children: [
      new Paragraph({ ...sp(400, 0), alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", size: 38, bold: true, color: GOLD, font: "Arial" })] }),
      new Paragraph({ ...sp(0, 0), alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "Month 1 Facebook Group Posts", size: 26, color: WHITE, font: "Arial" })] }),
      new Paragraph({ ...sp(0, 400), alignment: AlignmentType.CENTER,
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        children: [new TextRun({ text: "3 posts per week  |  Mon, Wed, Fri", size: 19, color: GOLD, italics: true, font: "Arial" })] }),
      spacer(),
      divider(),

      ...posts.flatMap((post, i) => [
        dayLabel(post.day, post.type),
        ...postBody(post.text),
        spacer(),
        hashLine(post.hashtags),
        i < posts.length - 1 ? divider() : spacer(),
      ]),

      spacer(),
      new Paragraph({ ...sp(160, 80), alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "The Luxora Collective  |  theluxoracollective.co", size: 17, color: GRAY, font: "Arial" })] }),
    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync("/mnt/user-data/outputs/Luxora_Month1_Posts_YourVoice.docx", buf);
  console.log("Done");
});

